      role1 = 1113000,
      role2 = 101103,
      role3 = 101202,
      role6 = 11135003,
      roleanim = 1.1,
      sentence = "I turned toward him, my fingers pressing on his chin as I straddled the throne — He leaned back in the chair, giving me enough space to be the assertive one.",
