      role1 = 368000,
      role2 = 301106,
      role3 = 301201,
      ruchang = -1,
      sentence = "剪辑视频的时候我才发现。原来我漏掉了那么多，$u不经意流露的可爱。",
      voice = 1,
      next = {10103}
    },
    [10103] = {
      beijing = 203020,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "1030_2024anniversary_pv",
      renming = "周棋洛",
      renwu = "npc",
      role1 = 368000,
      role2 = 301106,
      role3 = 301201,
      sentence = "这种感觉很……惊喜，像是又重新认识了你一遍。",
      voice = 1,
      next = {10104}
    },
    [10104] = {
      beijing = 203020,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "1030_2024anniversary_pv",
      renming = "周棋洛",
      renwu = "npc",
      role1 = 368000,
      role2 = 301106,
      role3 = 301201,
      sentence = "我很高兴。",
      voice = 1,
      next = {10105}
    },
    [10105] = {
      beijing = 203020,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "1030_2024anniversary_pv",
      renming = "周棋洛",
      renwu = "npc",
      role1 = 368000,
      role2 = 301106,
      role3 = 301201,
      sentence = "原来我还没有知晓你的全部，原来……我的宝藏还有这么多闪闪发光的地方。",
      voice = 1,
      next = {10106}
    },
    [10106] = {
      beijing = 203020,
      dhead = 107,
      dialog = 1,
      music = "1030_2024anniversary_pv",
      renming = "$u",
      renwu = "npc",
      role1 = 368000,
      role2 = 301106,
      role3 = 301201,
      sentence = "可能因为，我们一直都在变化吧？昨天的我和今天的我会不一样——",
      next = {10107}
    },
    [10107] = {
      beijing = 203020,
      dhead = 107,
      dialog = 1,
      music = "1030_2024anniversary_pv",
      renming = "$u",
      renwu = "npc",
      role1 = 368000,
      role2 = 301106,
      role3 = 301201,
      sentence = "明天的你，也一定比今天的你多了一些我不知道的东西。",
      next = {10108}
    },
    [10108] = {
      beijing = 203020,
      dialog = 3,
      music = "1030_2024anniversary_pv",
      renwu = "npc",
      role1 = 368000,
      role2 = 301102,
      role3 = 301201,
      sentence = "尽管我们早就已经习惯在一起了，也总以为自己熟知对方的一切。",
      next = {10109}
    },
    [10109] = {
      beijing = 203020,
      dialog = 3,
      music = "1030_2024anniversary_pv",
      renwu = "npc",
      role1 = 368000,
      role2 = 301102,
      role3 = 301201,
      sentence = "但依然有无数细小的变化填满生活的每一寸，无时无刻不嵌合在一起，彼此磨合，组成新的生活。",
      next = {10110}
    },
    [10110] = {
      beijing = 203020,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "1030_2024anniversary_pv",
      renming = "周棋洛",
      renwu = "npc",
      role1 = 368000,
      role2 = 301106,
      role3 = 301201,
      sentence = "小的时候，我总是迫不及待地想要改变，想要变成一个能够足以保护你的人。",
      voice = 1,
      next = {10111}
    },
    [10111] = {
      beijing = 203020,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "1030_2024anniversary_pv",
      renming = "周棋洛",
      renwu = "npc",
      role1 = 368000,
      role2 = 301106,
      role3 = 301201,
      sentence = "但后来，我又有些害怕。我不知道究竟什么样的变化才是正确的，是好的。",
      voice = 1,
      next = {10112}
    },
    [10112] = {
      beijing = 203020,
      dialog = 3,
      music = "1030_2024anniversary_pv",
      renwu = "npc",
      role1 = 368000,
      role2 = 301106,
      role3 = 301201,
      sentence = "他看着我，像透过我的眼睛，看向曾经的自己。",
      next = {10113}
    },
    [10113] = {
      beijing = 203020,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "1030_2024anniversary_pv",
      renming = "周棋洛",
      renwu = "npc",
      role1 = 368000,
      role2 = 301106,
      role3 = 301201,
      sentence = "但现在我不太担心了，反而……特别期待。",
      voice = 1,
      next = {10114}
    },
    [10114] = {
      beijing = 203020,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "1030_2024anniversary_pv",
      renming = "周棋洛",
      renwu = "npc",
      role1 = 368000,
      role2 = 301106,
      role3 = 301201,
      sentence = "因为你爱我。你的爱，让我变成了一个特别特别好的人。",
      voice = 1,
